import type { Theme } from 'vitepress'
import DefaultTheme from 'vitepress/theme'
import { useDokka } from '@graphglue/dokka-vitepress/client'

// Order matters for these three. `base.css` builds the page frame and is meant to lose against
// Dokka's own rules; `dokka.css` is Dokka's stylesheet, scoped to the embedded content; and
// `theme.css` re-skins it in VitePress' design tokens, so it has to come last.
import '@graphglue/dokka-vitepress/base.css'
// Generated by `npm run api` from the Dokka output. `scripts/docs.mjs` writes an empty
// placeholder when the Kotlin docs have not been built, so this import always resolves.
import '../dokka/dokka.css'
import '@graphglue/dokka-vitepress/theme.css'
// Order-independent: styles the generated entries in VitePress' own sidebar.
import '@graphglue/dokka-vitepress/sidebar.css'

import './custom.css'

export default {
    extends: DefaultTheme,
    enhanceApp({ app }) {
        useDokka(app)
    }
} satisfies Theme
